export type ParsedProviderSupplyInstruction<
  TProgram extends string = typeof AGARI_LEVERAGE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    provider: TAccountMetas[0];
    /** This wallet's own share balance. Created on first supply; never writable by anyone else. */
    record: TAccountMetas[1];
    reserve: TAccountMetas[2];
    custody: TAccountMetas[3];
    seat: TAccountMetas[4];
    providerToken: TAccountMetas[5];
    collateralMint: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: ProviderSupplyInstructionData;
};

export function parseProviderSupplyInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedProviderSupplyInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      provider: getNextAccount(),
      record: getNextAccount(),
      reserve: getNextAccount(),
      custody: getNextAccount(),
      seat: getNextAccount(),
      providerToken: getNextAccount(),
      collateralMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getProviderSupplyInstructionDataDecoder().decode(instruction.data),
  };
}
